// Shape of the hand-written teaching and finding texts (PRD sections 8, 11, 12).
// Texts are written by people, reviewed for statistical correctness, and never generated by the AI.
import type { Finding, Locale, RuleId, Verdict } from "../../stats/types";

/** Already-formatted numbers from the user's own test, for the dynamic parts of layer 1. */
export interface ExplanationContext {
  probabilityToBeat?: string; // "97,0%"
  pValue?: string; // "0,031"
  lift?: string; // "6,00%"
  mde?: string; // "8,4%"
  confidence?: string; // "95%"
  power?: string; // "80%"
  alpha?: string; // "2,5%"
  groups?: number;
  expectedLoss?: string; // "0,02 p.p."
  look?: number;
  plannedLooks?: number;
}

export type ConceptId =
  | "bayes"
  | "ztest"
  | "bayes-vs-z"
  | "p-value"
  | "confidence-power"
  | "mde-sample"
  | "hypothesis"
  | "bonferroni"
  | "expected-risk"
  | "srm"
  | "peeking-sequential";

export interface Explanation {
  title: string;
  /** Plain-language paragraph with an analogy and no formula. Uses ctx when the user has data. */
  layer1: (ctx: ExplanationContext | null) => string;
  /** "Ver detalhes": formulas, assumptions, and when the method misleads. Paragraphs separated by blank lines; formulas wrapped in backticks. */
  layer2: string;
}

/** Prewritten text for a rule finding: the UI fallback and what the AI must explain. */
export interface FindingText {
  title: string;
  explanation: string;
  action: string;
}

/** Number formatter injected by the UI so content never formats numbers itself. */
export interface Fmt {
  pct: (fraction: number, digits?: number) => string;
  num: (n: number, digits?: number) => string;
  int: (n: number) => string;
}

export interface HeadlineInput {
  verdict: Verdict;
  variantName: string;
  controlName: string;
  lift: number | null; // relative, may be negative
  probabilityToBeat: number | null; // bayesian
  pValue: number | null; // z test
  method: "bayesian" | "ztest";
}

export interface ContentPack {
  locale: Locale;
  explanations: Record<ConceptId, Explanation>;
  finding: (f: Finding, fmt: Fmt) => FindingText;
  ruleTitle: Record<RuleId, string>;
  headline: (h: HeadlineInput, fmt: Fmt) => string;
  verdictLabel: Record<Verdict, string>;
}
